// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    Caller h;

    function setUp() public {
        c = new MONEY_BOX();
        h = new Caller();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        Log l = new Log();
        // initialize via the very caller whose Put we later check
        vm.prank(address(h));
        c.SetLogFile(address(l));

        vm.deal(address(h), amount);
        vm.prank(address(h));
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Caller {
    constructor() payable {}
    receive() external payable {}
}
